    'dwz.p13':                '¿Crees que 50 $ cada 2 semanas no es suficiente para cambiar tu vida? Deja que los números hablen.',
    'dwz.p14':                '<strong>50 $ × 26 veces/año = 1 300 $/año invertido.</strong> Total en 20 años: <strong>26 000 $ de tu bolsillo.</strong>',
    'dwz.proj.low.label':     'Escenario conservador',
    'dwz.proj.mid.label':     'Escenario realista',
